mapper.select:
SELECT id, watch_id, `date`, action_type, sentiment, target_buy_price, target_buy_price_high, target_sell_price, target_sell_price_high, stop_loss_price, stop_loss_price_high, buy_share_count, sell_share_count, loss_share_count, note, next_day_note, review_result, review_note, created_at, updated_at FROM stock_daily_analysis WHERE watch_id IN
#{watchId}
ORDER BY `date` DESC

mapper.update:
UPDATE stock_daily_analysis
action_type = #{actionType}, sentiment = #{sentiment}, target_buy_price = #{targetBuyPrice}, target_buy_price_high = #{targetBuyPriceHigh}, target_sell_price = #{targetSellPrice}, target_sell_price_high = #{targetSellPriceHigh}, stop_loss_price = #{stopLossPrice}, stop_loss_price_high = #{stopLossPriceHigh}, buy_share_count = #{buyShareCount}, sell_share_count = #{sellShareCount}, loss_share_count = #{lossShareCount}, note = #{note}, next_day_note = #{nextDayNote}, review_result = #{reviewResult}, review_note = #{reviewNote}, updated_at = #{updatedAt}
WHERE id = #{id}
